class FrontMiddleBackQueue {
    private Deque<Integer> left = new ArrayDeque<>();
    private Deque<Integer> right = new ArrayDeque<>();

    private void balance() {
        if (left.size() > right.size()) {
            right.addFirst(left.removeLast());
        } else if (right.size() > left.size() + 1) {
            left.addLast(right.removeFirst());
        }
    }

    public FrontMiddleBackQueue() {}

    public void pushFront(int val) {
        left.addFirst(val);
        balance();
    }

    public void pushMiddle(int val) {
        if (left.size() == right.size()) {
            right.addFirst(val);
        } else {
            left.addLast(val);
        }
        balance();
    }

    public void pushBack(int val) {
        right.addLast(val);
        balance();
    }

    public int popFront() {
        if (left.isEmpty() && right.isEmpty()) return -1;
        int ans = !left.isEmpty() ? left.removeFirst() : right.removeFirst();
        balance();
        return ans;
    }

    public int popMiddle() {
        if (left.isEmpty() && right.isEmpty()) return -1;
        int ans = (left.size() == right.size()) ? left.removeLast() : right.removeFirst();
        balance();
        return ans;
    }

    public int popBack() {
        if (left.isEmpty() && right.isEmpty()) return -1;
        int ans = right.removeLast();
        balance();
        return ans;
    }
}

